import{_ as a,o as n,c as t,a2 as i}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Account – User Management","description":"","frontmatter":{"title":"Account – User Management"},"headers":[],"relativePath":"operations-knowledge-base/presales-support/account-user-management.md","filePath":"operations-knowledge-base/presales-support/account-user-management.md","lastUpdated":1794292919000}'),s={name:"operations-knowledge-base/presales-support/account-user-management.md"};function o(r,e,c,l,h,d){return n(),t("div",null,[...e[0]||(e[0]=[i('<h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>The “User Management” feature provides users with a convenient way to manage account permissions and invite new users.</p><p>Through the “User Management” interface, users can view existing user information clearly and manage permissions as needed. At the same time, they can invite new users to join and assign permissions flexibly, helping meet the needs of team collaboration and multi-role management while improving both efficiency and account security.</p><h2 id="_2-user-management-features" tabindex="-1">2. User Management Features <a class="header-anchor" href="#_2-user-management-features" aria-label="Permalink to &quot;2. User Management Features&quot;">​</a></h2><h3 id="_1-access-path" tabindex="-1">(1) Access Path <a class="header-anchor" href="#_1-access-path" aria-label="Permalink to &quot;(1) Access Path&quot;">​</a></h3><p>Users can navigate to Top-right profile icon → User Management to enter the “User Management” interface, where they can view and manage existing user information.</p><h3 id="_2-existing-user-information-display" tabindex="-1">(2) Existing User Information Display <a class="header-anchor" href="#_2-existing-user-information-display" aria-label="Permalink to &quot;(2) Existing User Information Display&quot;">​</a></h3><p>The “User Management” page displays added users in a list format, including the following key information:</p><h4 id="email-address" tabindex="-1">Email Address <a class="header-anchor" href="#email-address" aria-label="Permalink to &quot;Email Address&quot;">​</a></h4><p>Displays the user’s email address, which serves as one of the user’s primary identifiers.</p><h4 id="last-login-time" tabindex="-1">Last Login Time <a class="header-anchor" href="#last-login-time" aria-label="Permalink to &quot;Last Login Time&quot;">​</a></h4><p>Shows the last time the user logged in to the platform, helping users understand account activity.</p><h4 id="account-role" tabindex="-1">Account Role <a class="header-anchor" href="#account-role" aria-label="Permalink to &quot;Account Role&quot;">​</a></h4><p>Indicates the user’s role within the account, such as “Owner”, which represents the highest level of account permissions.</p><h4 id="action-options" tabindex="-1">Action Options <a class="header-anchor" href="#action-options" aria-label="Permalink to &quot;Action Options&quot;">​</a></h4><p>Each user entry provides two management options:</p><ul><li>Manage Permissions</li><li>Remove Access</li></ul><h3 id="_3-user-permission-management" tabindex="-1">(3) User Permission Management <a class="header-anchor" href="#_3-user-permission-management" aria-label="Permalink to &quot;(3) User Permission Management&quot;">​</a></h3><h4 id="manage-permissions" tabindex="-1">Manage Permissions <a class="header-anchor" href="#manage-permissions" aria-label="Permalink to &quot;Manage Permissions&quot;">​</a></h4><p>Click the “Manage Permissions” button to open the permission management page for the selected user. Based on business needs, users can assign or adjust permissions such as updating account information or managing products and services (specific permissions depend on the platform configuration).</p><h4 id="remove-access" tabindex="-1">Remove Access <a class="header-anchor" href="#remove-access" aria-label="Permalink to &quot;Remove Access&quot;">​</a></h4><p>If a user no longer needs access to the platform account, click “Remove Access” to revoke that user’s access and management permissions.</p><h2 id="_3-invite-new-users" tabindex="-1">3. Invite New Users <a class="header-anchor" href="#_3-invite-new-users" aria-label="Permalink to &quot;3. Invite New Users&quot;">​</a></h2><h3 id="_1-access-point" tabindex="-1">(1) Access Point <a class="header-anchor" href="#_1-access-point" aria-label="Permalink to &quot;(1) Access Point&quot;">​</a></h3><p>At the bottom of the “User Management” page, there is an “Invite New User” section where users can invite new members.</p><h3 id="_2-invitation-process" tabindex="-1">(2) Invitation Process <a class="header-anchor" href="#_2-invitation-process" aria-label="Permalink to &quot;(2) Invitation Process&quot;">​</a></h3><h4 id="enter-email-address" tabindex="-1">Enter Email Address <a class="header-anchor" href="#enter-email-address" aria-label="Permalink to &quot;Enter Email Address&quot;">​</a></h4><p>Enter the invitee’s email address in the input field and make sure it is correct.</p><h4 id="select-permission-type" tabindex="-1">Select Permission Type <a class="header-anchor" href="#select-permission-type" aria-label="Permalink to &quot;Select Permission Type&quot;">​</a></h4><ul><li><strong>All Permissions</strong> - The invited user will receive a higher level of account permissions and be able to perform more account operations.</li><li><strong>Choose Permissions</strong> - Users can manually select specific permissions based on actual needs and assign customized access rights to the invitee.</li></ul><h4 id="send-invitation" tabindex="-1">Send Invitation <a class="header-anchor" href="#send-invitation" aria-label="Permalink to &quot;Send Invitation&quot;">​</a></h4><p>After entering the email address and selecting the permission type, click “Send Invite”. The system will send an invitation link to the invitee’s email address.</p><h3 id="_3-invitee-handling-the-invitation" tabindex="-1">(3) Invitee Handling the Invitation <a class="header-anchor" href="#_3-invitee-handling-the-invitation" aria-label="Permalink to &quot;(3) Invitee Handling the Invitation&quot;">​</a></h3><h4 id="existing-account" tabindex="-1">Existing Account <a class="header-anchor" href="#existing-account" aria-label="Permalink to &quot;Existing Account&quot;">​</a></h4><p>If the invitee already has a platform account, clicking the invitation link will associate their account with the current account, allowing them to access and operate related resources based on the assigned permissions.</p><h4 id="no-existing-account" tabindex="-1">No Existing Account <a class="header-anchor" href="#no-existing-account" aria-label="Permalink to &quot;No Existing Account&quot;">​</a></h4><p>If the invitee does not have a platform account, clicking the invitation link will guide them to register a new account. Once registration is completed, they will automatically join the current account and receive the assigned permissions.</p><p>Through the “User Management” and “Invite New User” features, the platform provides users with an efficient account collaboration and permission management system, helping them manage account users more easily, support team collaboration, and improve both account security and coordination.</p>',38)])])}const p=a(s,[["render",o]]);export{u as __pageData,p as default};
